out = {"src_files": [], "docs_files": [], "content": {}}
def walk(path, acc):
    for name in repo.list(path):
        full = path + name if path == "" else path + "/" + name
        if name.endswith("/"):
            walk(full, acc)
        else:
            acc.append(full)
walk("src", out["src_files"])
walk("docs", out["docs_files"])
for f in out["src_files"] + out["docs_files"]:
    out["content"][f] = repo.read(f)
# also check case-insensitive / variant matches
out["variants"] = ["%s:%d: %s" % (h.path, h.line, h.text) for h in repo.search("(?i)v1_?tag", glob="**")]
return out
